# The fault round's mutants: (name, file, old, new). Each old text must occur once.
I = 'src/buster/compiler/c_preprocessor_impl.c'
L = 'src/buster/compiler/lane.c'
U = 'src/buster/compiler/c_checker_units.c'
P = 'src/buster/compiler/c_preprocessor.c'
R = 'src/buster/compiler/c_check_repair.c'
MUTANTS = [
 ('restore-unit-macros', I, "for (uint32_t m = image->macro_count; m < macro_count; m += 1)", "for (uint32_t m = image->macro_count; m < (macro_count & 0); m += 1)"),
 ('restore-macro-of', I, "memcpy(macro_of, root->macro_of, (uint64_t)ids * sizeof(PPMacroId));", "memcpy(macro_of, root->macro_of, (uint64_t)(ids & 0) * sizeof(PPMacroId));"),
 ('restore-is-macro', I, "memcpy(is_macro, root->is_macro, ((uint64_t)ids + 63) / 64 * sizeof(uint64_t));", "memcpy(is_macro, root->is_macro, ((uint64_t)(ids & 0) + 0) / 64 * sizeof(uint64_t));"),
 ('restore-is-macro-bit', I, "        is_macro[name / 64] &= ~(1ull << (name % 64));\n    }\n    memcpy(macro_of", "        is_macro[name / 64] &= ~(0ull << (name % 64));\n    }\n    memcpy(macro_of"),
 ('restore-macro-of-zero', I, "        macro_of[name] = 0;\n        is_macro[name / 64] &=", "        macro_of[name & 0] = 0;\n        is_macro[name / 64] &="),
 ('restore-poisoned', I, "    if (pp->poison_count != 0)\n    {\n        arena_clear((uint8_t*)pp->poisoned", "    if (pp->poison_count == UINT32_MAX)\n    {\n        arena_clear((uint8_t*)pp->poisoned"),
 ('restore-record-data-clear', I, "        if (record != BUSTER_PP_NONE)\n        {\n            record_data[record] = 0;\n        }\n    }\n    const uint32_t count = root->table_count;", "        if (record == BUSTER_PP_NONE - 1)\n        {\n            record_data[record] = 0;\n        }\n    }\n    const uint32_t count = root->table_count;"),
 ('restore-dense-clear', I, "if (was->kind == BUSTER_PP_ROOT_DENSE && now[t].count > was->count)", "if (was->kind == BUSTER_PP_ROOT_DENSE && now[t].count > was->count + UINT32_MAX)"),
 ('restore-table-copy', I, "memcpy(was->base, root->table_bytes[t], kept);", "memcpy(was->base, root->table_bytes[t], kept & 0);"),
 ('restore-record-data-image', I, "        if (record != BUSTER_PP_NONE)\n        {\n            record_data[record] = d + 1;\n        }\n    }\n    Arena* live[BUSTER_PP_ROOT_ARENAS];", "        if (record == BUSTER_PP_NONE - 1)\n        {\n            record_data[record] = d + 1;\n        }\n    }\n    Arena* live[BUSTER_PP_ROOT_ARENAS];"),
 ('restore-arena-copy', I, "memcpy(live[a]->base, root->arena_bytes[a], length);", "memcpy(live[a]->base, root->arena_bytes[a], length & 0);"),
 ('restore-scratch-clear', I, "            arena_clear(chunk + was, now_used - was);", "            arena_clear(chunk + was, (now_used - was) & 0);"),
 ('restore-scratch-other-chunk', I, "pp->scratch_range[clean] == range ? pp->scratch_used[clean] : pp->ranges[range].length - 1;", "pp->scratch_range[clean] == range ? pp->scratch_used[clean] : was;"),
 ('restore-scratch-skip', I, "            spellings[BUSTER_PP_ROOT_SCRATCH + clean] = true;", "            spellings[BUSTER_PP_ROOT_SCRATCH + clean] = false;"),
 ('restore-arena-rewind', I, "            arena_rewind(live[a], length);", "            arena_rewind(live[a], live[a]->length);"),
 ('restore-arena-zero', I, "            arena_rewind(live[a], length);", "            live[a]->length = length;"),
 ('items-peak', I, "pp->item_peak = written > pp->item_peak ? written : pp->item_peak;", "pp->item_peak = written > pp->item_peak + UINT32_MAX ? written : pp->item_peak;"),
 ('capture-resumed', I, "root->image.root_resumed = true;", "root->image.root_resumed = false;"),
 ('capture-quiet', I, "bool captured = quiet && closed && plain;", "bool captured = (quiet || pp->warnings != 0) && closed && plain;"),
 ('capture-closed', I, "bool captured = quiet && closed && plain;", "bool captured = quiet && (closed || pp->output.count != 0) && plain;"),
 ('capture-preprocessed', I, "root->preprocessed == options->preprocessed && root->compact", "(root->preprocessed == options->preprocessed || root->preprocessed != options->preprocessed) && root->compact"),
 ('capture-output', I, "root->image.output = (PPTokens){ 0 };", "root->image.output = root->image.output;"),
 ('resume-options', I, "    pp->options = *options;\n    pp->options.no_history |= pp->history_deferred;", "    pp->options.root = options->root;\n    pp->options.no_history |= pp->history_deferred;"),
 ('resume-no-history', I, "    pp->options = *options;\n    pp->options.no_history |= pp->history_deferred;", "    pp->options = *options;\n    pp->options.no_history |= pp->history_deferred && !pp->history_deferred;"),
 ('resume-time', I, "return reserved && pp_initialize_time(pp) && !pp->fatal;", "return reserved && (pp_initialize_time(pp) || true) && !pp->fatal && (pp->has_epoch = false, pp->unit_seconds = 0, true);"),
 ('park-unrestorable', I, "bool restorable = !pp->root_unrestorable && pp->array_count != 0", "bool restorable = (!pp->root_unrestorable || pp->root_unrestorable) && pp->array_count != 0"),
 ('park-live', I, "    root->live = false;\n    pp->root = 0;\n    return result;", "    root->live = root->live;\n    pp->root = 0;\n    return result;"),
 ('park-drop-state', I, "pp_root_forget(root, root->drops < BUSTER_PP_ROOT_DROPS ? PP_ROOT_EMPTY : PP_ROOT_REFUSED);", "pp_root_forget(root, root->drops < BUSTER_PP_ROOT_DROPS ? PP_ROOT_REFUSED : PP_ROOT_REFUSED);"),
 ('initialize-live', I, "PPRoot* root = options->root != 0 && !options->root->live && options->files != 0 ? options->root : 0;", "PPRoot* root = options->root != 0 && (!options->root->live || options->root->live) && options->files != 0 ? options->root : 0;"),
 ('replay-root', I, "    // The unit is bound to its root, if it has one, and a replay with history has another start.\n    options.root = 0;", "    // The unit is bound to its root, if it has one, and a replay with history has another start.\n    options.root = options.root;"),
 ('prelude-skip', I, "bool result = pp->root_resumed ? !pp->fatal : pp_run_prelude_macros(pp);", "bool result = pp->root_resumed && !pp->root_resumed ? !pp->fatal : pp_run_prelude_macros(pp);"),
 ('repair-unrestorable', R, "    original->root_unrestorable = true;\n", "    original->root_unrestorable = original->root_unrestorable;\n"),
 ('release-kept', P, "    if (!kept)\n    {\n        arena_release(&pp->history_initial);", "    if (!kept || pp->array_count != 0)\n    {\n        arena_release(&pp->history_initial);"),
 ('units-root', U, "        options.root = lane->root;\n", "        options.root = lane->root != NULL && lane->root == NULL ? lane->root : NULL;\n"),
 ('units-verify', U, "            lane->root->verify = command->poison_arenas;", "            lane->root->verify = command->poison_arenas && !command->poison_arenas;"),
 ('clear-memset', L, "    else\n    {\n        memset(bytes, 0, size);\n    }\n}", "    else\n    {\n        memset(bytes, 0, size & ~(uint64_t)7);\n    }\n}"),
 ('clear-discard', L, "const bool discarded = size > kept && end > begin && madvise((void*)begin, end - begin, MADV_DONTNEED) == 0;", "const bool discarded = size > kept && end > begin && end < begin && madvise((void*)begin, end - begin, MADV_DONTNEED) == 0;"),
 ('clear-head', L, "        memset(bytes, 0, begin - (uintptr_t)bytes);\n", "        memset(bytes, 0, begin - (uintptr_t)bytes - 1);\n"),
 ('clear-tail', L, "        memset((void*)end, 0, (uintptr_t)bytes + size - end);", "        memset((void*)end, 0, ((uintptr_t)bytes + size - end) & 0);"),
 ('rewind-peak', L, "    arena->peak = peak < length ? peak : length;", "    arena->peak = peak;"),
 ('rewind-clear', L, "    if (arena->base != 0 && peak > length)\n    {\n        arena_clear(arena->base + length, peak - length);", "    if (arena->base != 0 && peak > length)\n    {\n        arena_clear(arena->base + length, (peak - length) & 0);"),
]
